=== FILE: axi4_lite_regs.v ===
`timescale 1ns / 1ps
`default_nettype none

// axi4_lite_regs
// Four 32-bit read/write registers behind an AXI4-Lite subordinate port.
// Implements microarchitecture.md:
//   * READY is a function of state only (no combinational VALID->READY path).
//   * AW and W are captured in holding registers when they arrive alone; the
//     write fires on the edge that completes the pair.
//   * B and R responses are registered: latency 1 cycle, one outstanding
//     transaction per direction.
//   * Misaligned addresses answer SLVERR (2'b10); unmapped reads return 0.
module axi4_lite_regs #(
    parameter ADDR_WIDTH = 4,
    parameter DATA_WIDTH = 32
) (
    input  wire                    aclk,
    input  wire                    aresetn,
    // write address channel
    input  wire [ADDR_WIDTH-1:0]   s_axil_awaddr,
    input  wire                    s_axil_awvalid,
    output wire                    s_axil_awready,
    // write data channel
    input  wire [DATA_WIDTH-1:0]   s_axil_wdata,
    input  wire [DATA_WIDTH/8-1:0] s_axil_wstrb,
    input  wire                    s_axil_wvalid,
    output wire                    s_axil_wready,
    // write response channel
    output wire [1:0]              s_axil_bresp,
    output wire                    s_axil_bvalid,
    input  wire                    s_axil_bready,
    // read address channel
    input  wire [ADDR_WIDTH-1:0]   s_axil_araddr,
    input  wire                    s_axil_arvalid,
    output wire                    s_axil_arready,
    // read data channel
    output wire [DATA_WIDTH-1:0]   s_axil_rdata,
    output wire [1:0]              s_axil_rresp,
    output wire                    s_axil_rvalid,
    input  wire                    s_axil_rready
);

    localparam integer STRB_WIDTH = DATA_WIDTH / 8;
    localparam [1:0]   RESP_OKAY   = 2'b00;
    localparam [1:0]   RESP_SLVERR = 2'b10;

    // ------------------------------------------------------------------
    // Control state (reset)
    reg                  aw_held;
    reg                  w_held;
    reg                  bvalid_q;
    reg [1:0]            bresp_q;
    reg                  rvalid_q;
    reg [1:0]            rresp_q;
    reg [DATA_WIDTH-1:0] rdata_q;
    reg [DATA_WIDTH-1:0] reg0;
    reg [DATA_WIDTH-1:0] reg1;
    reg [DATA_WIDTH-1:0] reg2;
    reg [DATA_WIDTH-1:0] reg3;

    // Holding registers (datapath, not reset; qualified by the held flags)
    reg [ADDR_WIDTH-1:0] aw_addr_q;
    reg [DATA_WIDTH-1:0] w_data_q;
    reg [STRB_WIDTH-1:0] w_strb_q;

    // ------------------------------------------------------------------
    // Handshakes: READY from state only
    assign s_axil_awready = !aw_held && !bvalid_q;
    assign s_axil_wready  = !w_held  && !bvalid_q;
    assign s_axil_arready = !rvalid_q;

    wire aw_hs = s_axil_awvalid && s_axil_awready;
    wire w_hs  = s_axil_wvalid  && s_axil_wready;
    wire ar_hs = s_axil_arvalid && s_axil_arready;

    // The write fires on the edge that completes the AW/W pair.
    wire do_write = (aw_held || aw_hs) && (w_held || w_hs);

    // Held copy when one exists, else the live bus.
    wire [ADDR_WIDTH-1:0] wr_addr = aw_held ? aw_addr_q : s_axil_awaddr;
    wire [DATA_WIDTH-1:0] wr_data = w_held  ? w_data_q  : s_axil_wdata;
    wire [STRB_WIDTH-1:0] wr_strb = w_held  ? w_strb_q  : s_axil_wstrb;

    // ------------------------------------------------------------------
    // Address decode: mapped when word aligned and addr >> 4 == 0
    wire wr_high_zero;
    wire rd_high_zero;
    generate
        if (ADDR_WIDTH > 4) begin : g_addr_high
            assign wr_high_zero = ~|wr_addr[ADDR_WIDTH-1:4];
            assign rd_high_zero = ~|s_axil_araddr[ADDR_WIDTH-1:4];
        end else begin : g_addr_low
            assign wr_high_zero = 1'b1;
            assign rd_high_zero = 1'b1;
        end
    endgenerate

    wire       wr_mapped = (wr_addr[1:0] == 2'b00) && wr_high_zero;
    wire       rd_mapped = (s_axil_araddr[1:0] == 2'b00) && rd_high_zero;
    wire [1:0] wr_index  = wr_addr[3:2];
    wire [1:0] rd_index  = s_axil_araddr[3:2];

    // ------------------------------------------------------------------
    // Byte-enable merge: copy each byte whose strobe is set
    wire [DATA_WIDTH-1:0] wr_mask;
    genvar gi;
    generate
        for (gi = 0; gi < STRB_WIDTH; gi = gi + 1) begin : g_wr_mask
            assign wr_mask[8*gi +: 8] = {8{wr_strb[gi]}};
        end
    endgenerate

    wire [DATA_WIDTH-1:0] wr_next0 = (reg0 & ~wr_mask) | (wr_data & wr_mask);
    wire [DATA_WIDTH-1:0] wr_next1 = (reg1 & ~wr_mask) | (wr_data & wr_mask);
    wire [DATA_WIDTH-1:0] wr_next2 = (reg2 & ~wr_mask) | (wr_data & wr_mask);
    wire [DATA_WIDTH-1:0] wr_next3 = (reg3 & ~wr_mask) | (wr_data & wr_mask);

    // Read select
    reg [DATA_WIDTH-1:0] rd_sel;
    always @* begin
        case (rd_index)
            2'd0:    rd_sel = reg0;
            2'd1:    rd_sel = reg1;
            2'd2:    rd_sel = reg2;
            default: rd_sel = reg3;
        endcase
    end

    // ------------------------------------------------------------------
    // Control and register state
    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held  <= 1'b0;
            w_held   <= 1'b0;
            bvalid_q <= 1'b0;
            bresp_q  <= RESP_OKAY;
            rvalid_q <= 1'b0;
            rresp_q  <= RESP_OKAY;
            rdata_q  <= {DATA_WIDTH{1'b0}};
            reg0     <= {DATA_WIDTH{1'b0}};
            reg1     <= {DATA_WIDTH{1'b0}};
            reg2     <= {DATA_WIDTH{1'b0}};
            reg3     <= {DATA_WIDTH{1'b0}};
        end else begin
            // held flags
            if (do_write) begin
                aw_held <= 1'b0;
                w_held  <= 1'b0;
            end else begin
                if (aw_hs) aw_held <= 1'b1;
                if (w_hs)  w_held  <= 1'b1;
            end

            // write response
            if (do_write) begin
                bvalid_q <= 1'b1;
                bresp_q  <= wr_mapped ? RESP_OKAY : RESP_SLVERR;
            end else if (bvalid_q && s_axil_bready) begin
                bvalid_q <= 1'b0;
            end

            // register file
            if (do_write && wr_mapped) begin
                case (wr_index)
                    2'd0:    reg0 <= wr_next0;
                    2'd1:    reg1 <= wr_next1;
                    2'd2:    reg2 <= wr_next2;
                    default: reg3 <= wr_next3;
                endcase
            end

            // read response
            if (ar_hs) begin
                rvalid_q <= 1'b1;
                rresp_q  <= rd_mapped ? RESP_OKAY : RESP_SLVERR;
                rdata_q  <= rd_mapped ? rd_sel : {DATA_WIDTH{1'b0}};
            end else if (rvalid_q && s_axil_rready) begin
                rvalid_q <= 1'b0;
            end
        end
    end

    // Holding registers: capture a half that arrives without its partner
    always @(posedge aclk) begin
        if (aw_hs && !do_write) begin
            aw_addr_q <= s_axil_awaddr;
        end
        if (w_hs && !do_write) begin
            w_data_q <= s_axil_wdata;
            w_strb_q <= s_axil_wstrb;
        end
    end

    assign s_axil_bvalid = bvalid_q;
    assign s_axil_bresp  = bresp_q;
    assign s_axil_rvalid = rvalid_q;
    assign s_axil_rresp  = rresp_q;
    assign s_axil_rdata  = rdata_q;

`ifdef FORMAL
    // Design-intent properties (not proven in this task).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge aclk) f_past_valid <= 1'b1;

    // Manager assumptions
    always @(*) begin
        if (!f_past_valid) assume (!aresetn);
        if (!aresetn) begin
            assume (!s_axil_awvalid);
            assume (!s_axil_wvalid);
            assume (!s_axil_arvalid);
        end
    end

    always @(posedge aclk) begin
        if (f_past_valid && $past(aresetn) && aresetn) begin
            if ($past(s_axil_awvalid && !s_axil_awready)) begin
                assume (s_axil_awvalid);
                assume (s_axil_awaddr == $past(s_axil_awaddr));
            end
            if ($past(s_axil_wvalid && !s_axil_wready)) begin
                assume (s_axil_wvalid);
                assume (s_axil_wdata == $past(s_axil_wdata));
                assume (s_axil_wstrb == $past(s_axil_wstrb));
            end
            if ($past(s_axil_arvalid && !s_axil_arready)) begin
                assume (s_axil_arvalid);
                assume (s_axil_araddr == $past(s_axil_araddr));
            end
        end
    end

    // Subordinate assertions
    always @(posedge aclk) begin
        if (f_past_valid && !$past(aresetn)) begin
            assert (!s_axil_bvalid);
            assert (!s_axil_rvalid);
            assert (!aw_held);
            assert (!w_held);
        end
        if (f_past_valid && $past(aresetn) && aresetn) begin
            if ($past(s_axil_bvalid && !s_axil_bready)) begin
                assert (s_axil_bvalid);
                assert (s_axil_bresp == $past(s_axil_bresp));
            end
            if ($past(s_axil_rvalid && !s_axil_rready)) begin
                assert (s_axil_rvalid);
                assert (s_axil_rresp == $past(s_axil_rresp));
                assert (s_axil_rdata == $past(s_axil_rdata));
            end
            if (!$past(s_axil_bvalid)) assert (s_axil_bvalid == $past(do_write));
            if (!$past(s_axil_rvalid)) assert (s_axil_rvalid == $past(ar_hs));
        end
    end

    always @(*) begin
        if (f_past_valid) begin
            if (s_axil_bvalid) assert (!aw_held && !w_held);
            assert ((s_axil_bresp == RESP_OKAY) || (s_axil_bresp == RESP_SLVERR));
            assert ((s_axil_rresp == RESP_OKAY) || (s_axil_rresp == RESP_SLVERR));
            if (s_axil_rvalid && (s_axil_rresp == RESP_SLVERR))
                assert (s_axil_rdata == {DATA_WIDTH{1'b0}});
        end
    end

    always @(posedge aclk) begin
        if (f_past_valid && aresetn) begin
            cover (s_axil_bvalid && s_axil_bready && (s_axil_bresp == RESP_OKAY));
            cover (s_axil_rvalid && s_axil_rready && (s_axil_rresp == RESP_OKAY));
            cover (s_axil_rvalid && s_axil_rready && (s_axil_rresp == RESP_SLVERR));
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: axi4_lite_regs_tb.v ===
`timescale 1ns / 1ps
`define TICK begin @(posedge aclk); #1; end

// Self-checking testbench for axi4_lite_regs.
// Inputs change 1 ns after a rising edge; a protocol monitor samples on the
// falling edge (stable values for the next rising edge) and keeps its own
// register model. Directed tasks check returned data against a second model.
module axi4_lite_regs_tb;

    localparam [1:0]   OKAY    = 2'b00;
    localparam [1:0]   SLVERR  = 2'b10;
    localparam integer TIMEOUT = 32;
    localparam integer ORD_SAME  = 0;
    localparam integer ORD_AW1ST = 1;
    localparam integer ORD_W1ST  = 2;

    reg         aclk;
    reg         aresetn;
    reg  [3:0]  s_axil_awaddr;
    reg         s_axil_awvalid;
    wire        s_axil_awready;
    reg  [31:0] s_axil_wdata;
    reg  [3:0]  s_axil_wstrb;
    reg         s_axil_wvalid;
    wire        s_axil_wready;
    wire [1:0]  s_axil_bresp;
    wire        s_axil_bvalid;
    reg         s_axil_bready;
    reg  [3:0]  s_axil_araddr;
    reg         s_axil_arvalid;
    wire        s_axil_arready;
    wire [31:0] s_axil_rdata;
    wire [1:0]  s_axil_rresp;
    wire        s_axil_rvalid;
    reg         s_axil_rready;

    axi4_lite_regs #(
        .ADDR_WIDTH(4),
        .DATA_WIDTH(32)
    ) dut (
        .aclk           (aclk),
        .aresetn        (aresetn),
        .s_axil_awaddr  (s_axil_awaddr),
        .s_axil_awvalid (s_axil_awvalid),
        .s_axil_awready (s_axil_awready),
        .s_axil_wdata   (s_axil_wdata),
        .s_axil_wstrb   (s_axil_wstrb),
        .s_axil_wvalid  (s_axil_wvalid),
        .s_axil_wready  (s_axil_wready),
        .s_axil_bresp   (s_axil_bresp),
        .s_axil_bvalid  (s_axil_bvalid),
        .s_axil_bready  (s_axil_bready),
        .s_axil_araddr  (s_axil_araddr),
        .s_axil_arvalid (s_axil_arvalid),
        .s_axil_arready (s_axil_arready),
        .s_axil_rdata   (s_axil_rdata),
        .s_axil_rresp   (s_axil_rresp),
        .s_axil_rvalid  (s_axil_rvalid),
        .s_axil_rready  (s_axil_rready)
    );

    initial aclk = 1'b0;
    always #5 aclk = ~aclk;

    integer passed;
    integer failed;
    integer cyc;
    always @(posedge aclk) cyc <= cyc + 1;

    // ------------------------------------------------------------------
    // Checking and verdict
    task check;
        input          cond;
        input [8*64-1:0] msg;
        begin
            if (cond === 1'b1) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("[%0t] check failed: %0s", $time, msg);
            end
        end
    endtask

    reg [8*64-1:0] nonce;
    task finish_run;
        begin
            if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
            $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
            $finish;
        end
    endtask

    function [31:0] merge32;
        input [31:0] old;
        input [31:0] data;
        input [3:0]  strb;
        begin
            merge32 = old;
            if (strb[0]) merge32[7:0]   = data[7:0];
            if (strb[1]) merge32[15:8]  = data[15:8];
            if (strb[2]) merge32[23:16] = data[23:16];
            if (strb[3]) merge32[31:24] = data[31:24];
        end
    endfunction

    // ------------------------------------------------------------------
    // Models
    reg [31:0] tb_reg [0:3];   // directed model (write_chk / read_chk)
    reg [31:0] m_reg  [0:3];   // monitor model (observed handshakes)

    // Monitor state
    reg        m_aw_pend, m_w_pend;
    reg [3:0]  m_aw_addr;
    reg [31:0] m_w_data;
    reg [3:0]  m_w_strb;
    reg        b_exp_pend, b_seen, b_taken, b_taken_prev;
    reg [1:0]  b_exp_resp;
    integer    b_wait;
    reg        r_exp_pend, r_seen, r_taken, r_taken_prev;
    reg [1:0]  r_exp_resp;
    reg [31:0] r_exp_data;
    integer    r_wait;
    integer    rst_cnt;
    reg        after_rst;
    reg        aw_fire, w_fire, ar_fire, ord_aw, ord_w;
    integer    mi;

    // Coverage counters
    integer cov_aw_first, cov_w_first, cov_same;
    integer cov_bstall, cov_rstall;
    integer cov_slverr_w, cov_slverr_r;
    integer cov_partial, cov_zero;
    integer cov_rw_same, cov_b2b_w, cov_b2b_r, cov_rst_traffic;
    integer cov_wr [0:3];
    integer cov_rd [0:3];

    // ------------------------------------------------------------------
    // Protocol monitor and scoreboard
    always @(negedge aclk) begin
        if (aresetn !== 1'b1) begin
            if (rst_cnt > 0) begin
                check(s_axil_bvalid === 1'b0, "BVALID low during reset");
                check(s_axil_rvalid === 1'b0, "RVALID low during reset");
            end
            check(!s_axil_awvalid && !s_axil_wvalid && !s_axil_arvalid,
                  "manager VALIDs low during reset");
            if (rst_cnt == 0 && (b_exp_pend || r_exp_pend || m_aw_pend || m_w_pend))
                cov_rst_traffic = cov_rst_traffic + 1;
            rst_cnt = rst_cnt + 1;
            for (mi = 0; mi < 4; mi = mi + 1) m_reg[mi] = 32'h0;
            m_aw_pend  = 1'b0;
            m_w_pend   = 1'b0;
            b_exp_pend = 1'b0;
            r_exp_pend = 1'b0;
            b_seen     = 1'b0;
            r_seen     = 1'b0;
            b_taken    = 1'b0;
            r_taken    = 1'b0;
            after_rst  = 1'b1;
        end else begin
            rst_cnt = 0;
            if (after_rst) begin
                check(s_axil_awready && s_axil_wready && s_axil_arready,
                      "all READYs high after reset");
                after_rst = 1'b0;
            end
            b_taken_prev = b_taken;
            b_taken      = 1'b0;
            r_taken_prev = r_taken;
            r_taken      = 1'b0;
            if (b_taken_prev)
                check(s_axil_awready && s_axil_wready, "AW/W READY cycle after B taken");
            if (r_taken_prev)
                check(s_axil_arready, "ARREADY cycle after R taken");

            // ---- B channel
            if (b_exp_pend) begin
                b_wait = b_wait + 1;
                if (s_axil_bvalid === 1'b1) begin
                    if (!b_seen) begin
                        check(b_wait <= 2, "B latency at most 2 cycles");
                        b_seen = 1'b1;
                    end
                    check(s_axil_bresp === b_exp_resp, "BRESP matches model");
                    if (s_axil_bready === 1'b1) begin
                        b_exp_pend = 1'b0;
                        b_taken    = 1'b1;
                    end else begin
                        cov_bstall = cov_bstall + 1;
                    end
                end else begin
                    check(!b_seen, "BVALID held until taken");
                    if (!b_seen) check(b_wait < 2, "B latency at most 2 cycles");
                end
            end else begin
                check(s_axil_bvalid === 1'b0, "no B without a completed write");
            end

            // ---- R channel
            if (r_exp_pend) begin
                r_wait = r_wait + 1;
                if (s_axil_rvalid === 1'b1) begin
                    if (!r_seen) begin
                        check(r_wait <= 2, "R latency at most 2 cycles");
                        r_seen = 1'b1;
                    end
                    check(s_axil_rresp === r_exp_resp, "RRESP matches model");
                    check(s_axil_rdata === r_exp_data, "RDATA matches model");
                    if (s_axil_rready === 1'b1) begin
                        r_exp_pend = 1'b0;
                        r_taken    = 1'b1;
                    end else begin
                        cov_rstall = cov_rstall + 1;
                    end
                end else begin
                    check(!r_seen, "RVALID held until taken");
                    if (!r_seen) check(r_wait < 2, "R latency at most 2 cycles");
                end
            end else begin
                check(s_axil_rvalid === 1'b0, "no R without an accepted AR");
            end

            // ---- one outstanding transaction per direction
            if (s_axil_bvalid === 1'b1)
                check(!s_axil_awready && !s_axil_wready, "no write accepted while B pending");
            if (s_axil_rvalid === 1'b1)
                check(!s_axil_arready, "no read accepted while R pending");
            if (m_aw_pend) check(!s_axil_awready, "AWREADY low while AW held");
            if (m_w_pend)  check(!s_axil_wready, "WREADY low while W held");

            // ---- handshakes that happen at the next rising edge
            aw_fire = (s_axil_awvalid === 1'b1) && (s_axil_awready === 1'b1);
            w_fire  = (s_axil_wvalid  === 1'b1) && (s_axil_wready  === 1'b1);
            ar_fire = (s_axil_arvalid === 1'b1) && (s_axil_arready === 1'b1);
            if (b_taken_prev && (aw_fire || w_fire)) cov_b2b_w = cov_b2b_w + 1;
            if (r_taken_prev && ar_fire) cov_b2b_r = cov_b2b_r + 1;

            // reads see the register value before a write on the same edge
            if (ar_fire) begin
                if (s_axil_araddr[1:0] == 2'b00) begin
                    r_exp_data = m_reg[s_axil_araddr[3:2]];
                    r_exp_resp = OKAY;
                    cov_rd[s_axil_araddr[3:2]] = cov_rd[s_axil_araddr[3:2]] + 1;
                end else begin
                    r_exp_data   = 32'h0;
                    r_exp_resp   = SLVERR;
                    cov_slverr_r = cov_slverr_r + 1;
                end
                r_exp_pend = 1'b1;
                r_wait     = 0;
                r_seen     = 1'b0;
            end

            ord_aw = m_aw_pend;
            ord_w  = m_w_pend;
            if (aw_fire) begin
                m_aw_pend = 1'b1;
                m_aw_addr = s_axil_awaddr;
            end
            if (w_fire) begin
                m_w_pend = 1'b1;
                m_w_data = s_axil_wdata;
                m_w_strb = s_axil_wstrb;
            end
            if (m_aw_pend && m_w_pend) begin
                if (ord_aw)     cov_aw_first = cov_aw_first + 1;
                else if (ord_w) cov_w_first  = cov_w_first + 1;
                else            cov_same     = cov_same + 1;
                if (ar_fire) cov_rw_same = cov_rw_same + 1;
                if (m_aw_addr[1:0] == 2'b00) begin
                    m_reg[m_aw_addr[3:2]] = merge32(m_reg[m_aw_addr[3:2]], m_w_data, m_w_strb);
                    cov_wr[m_aw_addr[3:2]] = cov_wr[m_aw_addr[3:2]] + 1;
                    if (m_w_strb == 4'h0)      cov_zero    = cov_zero + 1;
                    else if (m_w_strb != 4'hF) cov_partial = cov_partial + 1;
                    b_exp_resp = OKAY;
                end else begin
                    b_exp_resp   = SLVERR;
                    cov_slverr_w = cov_slverr_w + 1;
                end
                b_exp_pend = 1'b1;
                b_wait     = 0;
                b_seen     = 1'b0;
                m_aw_pend  = 1'b0;
                m_w_pend   = 1'b0;
            end
        end
    end

    // ------------------------------------------------------------------
    // Channel drivers (called 1 ns after a rising edge)
    reg [1:0]  last_bresp;
    reg [1:0]  last_rresp;
    reg [31:0] last_rdata;

    task drive_aw(input [3:0] addr);
        integer t;
        reg     done;
        begin
            s_axil_awaddr  = addr;
            s_axil_awvalid = 1'b1;
            done = 1'b0;
            t    = 0;
            while (!done && t < TIMEOUT) begin
                done = (s_axil_awready === 1'b1);
                `TICK
                t = t + 1;
            end
            check(done, "AW handshake completes");
            s_axil_awvalid = 1'b0;
            s_axil_awaddr  = ~addr;
        end
    endtask

    task drive_w(input [31:0] data, input [3:0] strb);
        integer t;
        reg     done;
        begin
            s_axil_wdata  = data;
            s_axil_wstrb  = strb;
            s_axil_wvalid = 1'b1;
            done = 1'b0;
            t    = 0;
            while (!done && t < TIMEOUT) begin
                done = (s_axil_wready === 1'b1);
                `TICK
                t = t + 1;
            end
            check(done, "W handshake completes");
            s_axil_wvalid = 1'b0;
            s_axil_wdata  = ~data;
            s_axil_wstrb  = ~strb;
        end
    endtask

    task drive_ar(input [3:0] addr);
        integer t;
        reg     done;
        begin
            s_axil_araddr  = addr;
            s_axil_arvalid = 1'b1;
            done = 1'b0;
            t    = 0;
            while (!done && t < TIMEOUT) begin
                done = (s_axil_arready === 1'b1);
                `TICK
                t = t + 1;
            end
            check(done, "AR handshake completes");
            s_axil_arvalid = 1'b0;
            s_axil_araddr  = ~addr;
        end
    endtask

    task take_b(input integer stall);
        integer   t;
        reg [1:0] first_resp;
        begin
            s_axil_bready = 1'b0;
            t = 0;
            while ((s_axil_bvalid !== 1'b1) && t < TIMEOUT) begin
                `TICK
                t = t + 1;
            end
            check(s_axil_bvalid === 1'b1, "BVALID arrives");
            first_resp = s_axil_bresp;
            for (t = 0; t < stall; t = t + 1) `TICK
            check(s_axil_bvalid === 1'b1, "BVALID held through stall");
            check(s_axil_bresp === first_resp, "BRESP held through stall");
            last_bresp    = s_axil_bresp;
            s_axil_bready = 1'b1;
            `TICK
            s_axil_bready = 1'b0;
        end
    endtask

    task take_b_early;
        integer t;
        begin
            s_axil_bready = 1'b1;
            t = 0;
            while ((s_axil_bvalid !== 1'b1) && t < TIMEOUT) begin
                `TICK
                t = t + 1;
            end
            check(s_axil_bvalid === 1'b1, "BVALID arrives");
            last_bresp = s_axil_bresp;
            `TICK
        end
    endtask

    task take_r(input integer stall);
        integer    t;
        reg [1:0]  first_resp;
        reg [31:0] first_data;
        begin
            s_axil_rready = 1'b0;
            t = 0;
            while ((s_axil_rvalid !== 1'b1) && t < TIMEOUT) begin
                `TICK
                t = t + 1;
            end
            check(s_axil_rvalid === 1'b1, "RVALID arrives");
            first_resp = s_axil_rresp;
            first_data = s_axil_rdata;
            for (t = 0; t < stall; t = t + 1) `TICK
            check(s_axil_rvalid === 1'b1, "RVALID held through stall");
            check(s_axil_rresp === first_resp, "RRESP held through stall");
            check(s_axil_rdata === first_data, "RDATA held through stall");
            last_rresp    = s_axil_rresp;
            last_rdata    = s_axil_rdata;
            s_axil_rready = 1'b1;
            `TICK
            s_axil_rready = 1'b0;
        end
    endtask

    task take_r_early;
        integer t;
        begin
            s_axil_rready = 1'b1;
            t = 0;
            while ((s_axil_rvalid !== 1'b1) && t < TIMEOUT) begin
                `TICK
                t = t + 1;
            end
            check(s_axil_rvalid === 1'b1, "RVALID arrives");
            last_rresp = s_axil_rresp;
            last_rdata = s_axil_rdata;
            `TICK
        end
    endtask

    // ------------------------------------------------------------------
    // Directed transactions
    task write_chk(input [3:0] addr, input [31:0] data, input [3:0] strb,
                   input integer order, input integer gap, input integer bstall);
        reg [1:0] exp_resp;
        integer   g;
        begin
            exp_resp = (addr[1:0] == 2'b00) ? OKAY : SLVERR;
            fork
                begin
                    if (order == ORD_W1ST) for (g = 0; g < gap; g = g + 1) `TICK
                    drive_aw(addr);
                end
                begin
                    if (order == ORD_AW1ST) for (g = 0; g < gap; g = g + 1) `TICK
                    drive_w(data, strb);
                end
                take_b(bstall);
            join
            check(last_bresp === exp_resp, "BRESP of directed write");
            if (addr[1:0] == 2'b00)
                tb_reg[addr[3:2]] = merge32(tb_reg[addr[3:2]], data, strb);
        end
    endtask

    task read_chk(input [3:0] addr, input integer rstall);
        reg [31:0] exp_data;
        reg [1:0]  exp_resp;
        begin
            if (addr[1:0] == 2'b00) begin
                exp_data = tb_reg[addr[3:2]];
                exp_resp = OKAY;
            end else begin
                exp_data = 32'h0;
                exp_resp = SLVERR;
            end
            fork
                drive_ar(addr);
                take_r(rstall);
            join
            check(last_rdata === exp_data, "RDATA of directed read");
            check(last_rresp === exp_resp, "RRESP of directed read");
        end
    endtask

    // ------------------------------------------------------------------
    // Watchdog
    initial begin
        #100000;
        check(1'b0, "watchdog: simulation did not finish");
        finish_run;
    end

    // ------------------------------------------------------------------
    // Test sequence
    integer    i, ka, kw, kb, t0;
    reg [1:0]  resp_a;
    reg [31:0] data_a;

    initial begin
        passed = 0;
        failed = 0;
        cyc    = 0;
        rst_cnt = 0;
        after_rst = 1'b0;
        m_aw_pend = 1'b0; m_w_pend = 1'b0;
        b_exp_pend = 1'b0; r_exp_pend = 1'b0;
        b_seen = 1'b0; r_seen = 1'b0;
        b_taken = 1'b0; r_taken = 1'b0;
        b_taken_prev = 1'b0; r_taken_prev = 1'b0;
        b_wait = 0; r_wait = 0;
        cov_aw_first = 0; cov_w_first = 0; cov_same = 0;
        cov_bstall = 0; cov_rstall = 0;
        cov_slverr_w = 0; cov_slverr_r = 0;
        cov_partial = 0; cov_zero = 0;
        cov_rw_same = 0; cov_b2b_w = 0; cov_b2b_r = 0; cov_rst_traffic = 0;
        for (i = 0; i < 4; i = i + 1) begin
            cov_wr[i] = 0;
            cov_rd[i] = 0;
            tb_reg[i] = 32'h0;
            m_reg[i]  = 32'h0;
        end
        last_bresp = 2'b00;
        last_rresp = 2'b00;
        last_rdata = 32'h0;

        aresetn        = 1'b0;
        s_axil_awaddr  = 4'h0;
        s_axil_awvalid = 1'b0;
        s_axil_wdata   = 32'h0;
        s_axil_wstrb   = 4'h0;
        s_axil_wvalid  = 1'b0;
        s_axil_bready  = 1'b0;
        s_axil_araddr  = 4'h0;
        s_axil_arvalid = 1'b0;
        s_axil_rready  = 1'b0;

        repeat (4) @(posedge aclk);
        #1 aresetn = 1'b1;
        `TICK

        // 1. Reset values
        for (i = 0; i < 4; i = i + 1) read_chk({i[1:0], 2'b00}, 0);

        // 2. Write then read every register, all AW/W orderings
        write_chk(4'h0, 32'hA5A5_0F00, 4'hF, ORD_SAME,  0, 0);
        write_chk(4'h4, 32'h1234_5678, 4'hF, ORD_AW1ST, 2, 0);
        write_chk(4'h8, 32'hDEAD_BEEF, 4'hF, ORD_W1ST,  3, 0);
        write_chk(4'hC, 32'hCAFE_F00D, 4'hF, ORD_SAME,  0, 3);
        for (i = 0; i < 4; i = i + 1) read_chk({i[1:0], 2'b00}, i);
        write_chk(4'h0, 32'h0102_0304, 4'hF, ORD_AW1ST, 1, 1);
        write_chk(4'h4, 32'h8765_4321, 4'hF, ORD_W1ST,  1, 0);
        write_chk(4'h8, 32'h0F0F_F0F0, 4'hF, ORD_AW1ST, 4, 2);
        write_chk(4'hC, 32'h55AA_AA55, 4'hF, ORD_W1ST,  2, 0);
        for (i = 0; i < 4; i = i + 1) read_chk({i[1:0], 2'b00}, 3 - i);

        // 3. Byte strobes (REG2), including an empty strobe
        write_chk(4'h8, 32'h0000_0000, 4'hF,    ORD_SAME, 0, 0);
        write_chk(4'h8, 32'hAAAA_AA11, 4'b0001, ORD_SAME, 0, 0);
        read_chk(4'h8, 0);
        write_chk(4'h8, 32'hBBBB_22BB, 4'b0010, ORD_AW1ST, 1, 0);
        read_chk(4'h8, 0);
        write_chk(4'h8, 32'hCC33_CCCC, 4'b0100, ORD_W1ST, 1, 0);
        read_chk(4'h8, 0);
        write_chk(4'h8, 32'h44DD_DDDD, 4'b1000, ORD_SAME, 0, 1);
        read_chk(4'h8, 0);
        write_chk(4'h8, 32'hFFFF_FFFF, 4'b0000, ORD_SAME, 0, 0);
        read_chk(4'h8, 0);
        write_chk(4'h8, 32'h5566_7788, 4'b0101, ORD_SAME, 0, 0);
        read_chk(4'h8, 1);
        write_chk(4'h8, 32'h99AA_BBCC, 4'b1010, ORD_AW1ST, 2, 0);
        read_chk(4'h8, 0);
        write_chk(4'h0, 32'hFFFF_FFFF, 4'b0000, ORD_W1ST, 2, 2);
        write_chk(4'h4, 32'h1122_3344, 4'b0110, ORD_SAME, 0, 0);
        for (i = 0; i < 4; i = i + 1) read_chk({i[1:0], 2'b00}, 0);

        // 4. SLVERR policy: misaligned writes change nothing, reads return 0
        write_chk(4'h5, 32'hFFFF_FFFF, 4'hF, ORD_SAME,  0, 0);
        write_chk(4'hE, 32'hFFFF_FFFF, 4'hF, ORD_AW1ST, 1, 2);
        write_chk(4'h1, 32'hFFFF_FFFF, 4'hF, ORD_W1ST,  1, 0);
        write_chk(4'h3, 32'hFFFF_FFFF, 4'h0, ORD_SAME,  0, 0);
        read_chk(4'h5, 0);
        read_chk(4'hE, 2);
        read_chk(4'h2, 0);
        read_chk(4'hB, 1);
        for (i = 0; i < 4; i = i + 1) read_chk({i[1:0], 2'b00}, 0);

        // 5. Backpressure with a second request queued behind the response
        fork
            begin drive_aw(4'h0); drive_aw(4'h4); end
            begin drive_w(32'h0BAD_F00D, 4'hF); drive_w(32'h7777_8888, 4'hF); end
            begin take_b(5); resp_a = last_bresp; take_b(0); end
        join
        check(resp_a === OKAY, "BRESP of first queued write");
        check(last_bresp === OKAY, "BRESP of second queued write");
        tb_reg[0] = 32'h0BAD_F00D;
        tb_reg[1] = 32'h7777_8888;
        fork
            begin drive_ar(4'h0); drive_ar(4'h4); end
            begin take_r(6); data_a = last_rdata; resp_a = last_rresp; take_r(0); end
        join
        check(data_a === tb_reg[0], "RDATA of first queued read");
        check(resp_a === OKAY, "RRESP of first queued read");
        check(last_rdata === tb_reg[1], "RDATA of second queued read");
        check(last_rresp === OKAY, "RRESP of second queued read");
        // reads and writes stalled independently at the same time
        fork
            write_chk(4'hC, 32'h3C3C_C3C3, 4'hF, ORD_SAME, 0, 4);
            read_chk(4'h4, 5);
        join

        // 6. Back-to-back transfers with responses always accepted
        t0 = cyc;
        fork
            begin for (ka = 0; ka < 8; ka = ka + 1) drive_aw({ka[1:0], 2'b00}); end
            begin for (kw = 0; kw < 8; kw = kw + 1) drive_w(32'h1000_0000 + kw, 4'hF); end
            begin
                for (kb = 0; kb < 8; kb = kb + 1) begin
                    take_b_early;
                    check(last_bresp === OKAY, "BRESP back-to-back write");
                end
            end
        join
        s_axil_bready = 1'b0;
        check((cyc - t0) <= 18, "8 back-to-back writes in at most 18 cycles");
        for (i = 0; i < 4; i = i + 1) tb_reg[i] = 32'h1000_0004 + i;
        t0 = cyc;
        fork
            begin for (ka = 0; ka < 8; ka = ka + 1) drive_ar({ka[1:0], 2'b00}); end
            begin
                for (kb = 0; kb < 8; kb = kb + 1) begin
                    take_r_early;
                    check(last_rdata === tb_reg[kb[1:0]], "RDATA back-to-back read");
                    check(last_rresp === OKAY, "RRESP back-to-back read");
                end
            end
        join
        s_axil_rready = 1'b0;
        check((cyc - t0) <= 18, "8 back-to-back reads in at most 18 cycles");

        // 7. A read and a write on the same clock
        fork
            write_chk(4'h8, 32'h5A5A_A5A5, 4'hF, ORD_SAME, 0, 0);
            read_chk(4'h8, 0);   // returns the value before the write
        join
        read_chk(4'h8, 0);
        fork
            write_chk(4'hC, 32'h6969_9696, 4'hF, ORD_SAME, 0, 1);
            read_chk(4'h0, 1);
        join
        fork
            write_chk(4'h6, 32'hFFFF_FFFF, 4'hF, ORD_SAME, 0, 0);
            read_chk(4'h9, 0);
        join
        for (i = 0; i < 4; i = i + 1) read_chk({i[1:0], 2'b00}, 0);

        // 8. Reset during traffic: half-accepted write and pending read
        drive_aw(4'h0);          // AW held, no W
        drive_ar(4'h4);          // R left pending (RREADY low)
        `TICK
        `TICK
        aresetn = 1'b0;
        repeat (3) `TICK
        aresetn = 1'b1;
        for (i = 0; i < 4; i = i + 1) tb_reg[i] = 32'h0;
        `TICK
        check(s_axil_bvalid === 1'b0, "BVALID low after reset in traffic");
        check(s_axil_rvalid === 1'b0, "RVALID low after reset in traffic");
        drive_w(32'hFEED_FACE, 4'hF);   // must not pair with the discarded AW
        repeat (4) begin
            check(s_axil_bvalid === 1'b0, "no B from discarded AW");
            `TICK
        end
        fork
            drive_aw(4'h8);
            take_b(0);
        join
        check(last_bresp === OKAY, "BRESP after reset in traffic");
        tb_reg[2] = 32'hFEED_FACE;
        for (i = 0; i < 4; i = i + 1) read_chk({i[1:0], 2'b00}, 0);

        // 9. Coverage goals reached by the stimulus above
        check(cov_aw_first > 0, "cover: AW before W");
        check(cov_w_first > 0, "cover: W before AW");
        check(cov_same > 0, "cover: AW and W together");
        check(cov_bstall > 0, "cover: B backpressure");
        check(cov_rstall > 0, "cover: R backpressure");
        check(cov_slverr_w > 0, "cover: SLVERR write");
        check(cov_slverr_r > 0, "cover: SLVERR read");
        check(cov_partial > 0, "cover: partial strobe");
        check(cov_zero > 0, "cover: empty strobe");
        check(cov_rw_same > 0, "cover: read and write same clock");
        check(cov_b2b_w > 0, "cover: back-to-back write");
        check(cov_b2b_r > 0, "cover: back-to-back read");
        check(cov_rst_traffic > 0, "cover: reset during traffic");
        for (i = 0; i < 4; i = i + 1) begin
            check(cov_wr[i] > 0, "cover: write to every register");
            check(cov_rd[i] > 0, "cover: read of every register");
        end

        `TICK
        finish_run;
    end

endmodule
